 readonly Func<Settings> settings;readonly Func<IEnumerable<BoxWindow>> boxes;Window? window;readonly Canvas icons=new();readonly HashSet<string> selected=new(StringComparer.OrdinalIgnoreCase);IntPtr listHandle;string layoutKey="";bool disposed;Point dragOffset;string? selectionAnchor;
 internal DesktopLayer(Func<Settings> settings,Func<IEnumerable<BoxWindow>> boxes){this.settings=settings;this.boxes=boxes;icons.Background=Brushes.Transparent;icons.AllowDrop=true;icons.Focusable=true;icons.PreviewKeyDown+=DesktopKeyDown;icons.MouseLeftButtonDown+=(_,e)=>{if(ReferenceEquals(e.OriginalSource,icons)){selected.Clear();selectionAnchor=null;UpdateSelectionVisuals();icons.Focus();}};icons.DragOver+=(_,e)=>{if(!e.Data.GetDataPresent(RepositionFormat))return;e.Effects=DragDropEffects.Move;e.Handled=true;};icons.Drop+=RepositionDrop;}
 internal int DisplayedCount=>icons.Children.Count;
 internal bool Contains(string id)=>icons.Children.OfType<FrameworkElement>().Any(x=>string.Equals(x.Tag as string,id,StringComparison.OrdinalIgnoreCase));
 internal double RenderedIconPixels=>icons.Children.OfType<Border>().Select(x=>((StackPanel)x.Child).Children.OfType<Image>().First().Width*(window==null?1:VisualTreeHelper.GetDpi(window).DpiScaleX)).FirstOrDefault();
 internal bool Attached=>window!=null&&GetParent(new WindowInteropHelper(window).Handle)==GetParent(listHandle);
 internal void Refresh(){if(disposed)return;var visibleBoxes=boxes().Where(x=>x.IsVisible).ToArray();if(visibleBoxes.Length==0){Stop();return;}var collected=settings().Boxes.Where(x=>x.Folder==null).SelectMany(x=>x.Entries).ToHashSet(StringComparer.OrdinalIgnoreCase);var items=DesktopIcons.ReadAll();var native=FindList();if(native==IntPtr.Zero){Stop();if(collected.Count>0)throw new IOException("Explorer 桌面暂不可用");return;}if(window!=null&&native!=listHandle){window.Close();window=null;layoutKey="";listHandle=IntPtr.Zero;}if(window==null&&!IsWindowVisible(native)&&!File.Exists(Marker))return;GetClientRect(native,out var desktopRect);ReserveSlots(native,desktopRect,items,collected,visibleBoxes);if(collected.Count==0||!items.Any(x=>collected.Contains(x.Id))){Stop();return;}
  if(window==null){if(!IsWindowVisible(native)&&!File.Exists(Marker))return;listHandle=native;Directory.CreateDirectory(Path.GetDirectoryName(Marker)!);var temp=Marker+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(new Recovery(listHandle.ToInt64())));File.Move(temp,Marker,true);window=new Window{Title="桌面盒子 · 桌面图标层",WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,AllowsTransparency=true,Background=Brushes.Transparent,ShowInTaskbar=false,ShowActivated=false,Content=icons,Left=0,Top=0};window.SourceInitialized+=(_,_)=>{var handle=new WindowInteropHelper(window).Handle;var style=GetWindowLong(handle,-16);SetWindowLong(handle,-16,(style&~unchecked((int)0x80000000))|0x40000000);SetParent(handle,GetParent(listHandle));if(GetParent(handle)!=GetParent(listHandle))throw new IOException("系统拒绝桌面图标层嵌入");HwndSource.FromHwnd(handle).AddHook((IntPtr h,int msg,IntPtr w,IntPtr l,ref bool handled)=>{if(msg==0x21){handled=true;return new IntPtr(3);}return IntPtr.Zero;});};try{window.Show();}catch{Stop();throw;}}
  GetClientRect(listHandle,out var rect);var dpi=VisualTreeHelper.GetDpi(window);window.Width=Math.Max(1,(rect.Right-rect.Left)/dpi.DpiScaleX);window.Height=Math.Max(1,(rect.Bottom-rect.Top)/dpi.DpiScaleY);SetWindowPos(new WindowInteropHelper(window).Handle,IntPtr.Zero,0,0,rect.Right-rect.Left,rect.Bottom-rect.Top,0x54);
  var size=DesktopIcons.IconSize();var visible=items.Where(x=>!collected.Contains(x.Id)).ToArray();selected.IntersectWith(visible.Select(x=>x.Id));var key=$"{size}:{dpi.DpiScaleX}|"+string.Join("|",visible.Select(x=>$"{x.Id}:{x.Position.X},{x.Position.Y}"));if(key!=layoutKey){icons.Children.Clear();foreach(var item in visible)Add(item,dpi,size);layoutKey=key;UpdateSelectionVisuals();}ShowWindow(listHandle,0);if(IsWindowVisible(listHandle)){Stop();throw new IOException("系统不允许隐藏原桌面图标层");}
